import React, { useState, useEffect } from 'react';
import { C, slides } from '../data';

export default function Hero() {
  const [current, setCurrent] = useState(0);

  useEffect(() => {
    const t = setInterval(() => setCurrent((c) => (c + 1) % slides.length), 5000);
    return () => clearInterval(t);
  }, []);

  const prev = () => setCurrent((c) => (c - 1 + slides.length) % slides.length);
  const next = () => setCurrent((c) => (c + 1) % slides.length);
  const slide = slides[current];

  return (
    <section id="hero" style={{ 
      position: 'relative', 
      minHeight: '100vh', 
      display: 'flex', 
      alignItems: 'center', 
      overflow: 'hidden',
      backgroundColor: '#000' // Fallback color
    }}>

      {/* --- Main Background Image Layer --- */}
      <div style={{
        position: 'absolute',
        inset: 0,
        backgroundImage: `url(${slide.imageUrl})`,
        backgroundSize: 'cover',
        backgroundPosition: 'center',
        transition: 'background-image 1.2s ease-in-out, transform 10s linear',
        transform: 'scale(1.1)', // Subtle zoom effect
        zIndex: 1
      }} />

      {/* --- Modern Overlay for Text Readability --- */}
      <div style={{
        position: 'absolute',
        inset: 0,
        background: 'linear-gradient(to right, rgba(0,0,0,0.85) 0%, rgba(0,0,0,0.4) 60%, rgba(0,0,0,0.7) 100%)',
        zIndex: 2
      }} />

      {/* --- Content Area --- */}
      <div style={{ 
        maxWidth: 1280, 
        margin: '0 auto', 
        padding: '0 24px', 
        width: '100%', 
        position: 'relative', 
        zIndex: 3 
      }}>
        <div style={{ maxWidth: 700 }}>
          {/* Animated Tag */}
          <div style={{ 
            display: 'inline-flex', 
            alignItems: 'center', 
            gap: 8,
            padding: '8px 16px', 
            borderRadius: 8, 
            fontSize: 12, 
            fontWeight: 700, 
            textTransform: 'uppercase', 
            letterSpacing: '0.2em', 
            marginBottom: 24, 
            background: 'rgba(255,255,255,0.1)',
            backdropFilter: 'blur(10px)',
            borderLeft: `4px solid ${C.gold}`,
            color: C.goldLight
          }}>
            {slide.tag}
          </div>

          {/* Elegant Typography */}
          <h1 style={{ 
            fontSize: 'clamp(2.5rem, 8vw, 4.5rem)', 
            fontWeight: 800, 
            color: '#fff', 
            fontFamily: "'Playfair Display', serif", 
            lineHeight: 1.1, 
            marginBottom: 24,
            textShadow: '0 10px 30px rgba(0,0,0,0.5)'
          }}>
            {slide.title}
          </h1>

          <p style={{ 
            fontSize: 'clamp(1rem, 2vw, 1.25rem)', 
            color: 'rgba(255,255,255,0.8)', 
            marginBottom: 48, 
            lineHeight: 1.6, 
            maxWidth: 550 
          }}>
            {slide.subtitle}
          </p>

          {/* Action Buttons */}
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 20 }}>
            <button
              onClick={() => document.getElementById('contact')?.scrollIntoView({ behavior: 'smooth' })}
              style={{ 
                padding: '18px 44px', 
                borderRadius: 12, 
                fontWeight: 700, 
                fontSize: 16, 
                background: C.gold, 
                color: '#000', 
                border: 'none', 
                cursor: 'pointer', 
                boxShadow: `0 15px 35px ${C.gold}44`,
                transition: 'all 0.3s ease' 
              }}
              onMouseEnter={e => e.currentTarget.style.transform = 'translateY(-5px)'}
              onMouseLeave={e => e.currentTarget.style.transform = 'translateY(0)'}
            >
              Start Learning Free
            </button>

            <button
              style={{ 
                padding: '18px 44px', 
                borderRadius: 12, 
                fontWeight: 700, 
                fontSize: 16, 
                background: 'rgba(255,255,255,0.05)', 
                color: '#fff', 
                border: '1px solid rgba(255,255,255,0.3)', 
                cursor: 'pointer', 
                backdropFilter: 'blur(10px)',
                transition: 'all 0.3s' 
              }}
              onMouseEnter={e => e.currentTarget.style.background = 'rgba(255,255,255,0.15)'}
              onMouseLeave={e => e.currentTarget.style.background = 'rgba(255,255,255,0.05)'}
            >
              Explore Courses
            </button>
          </div>
        </div>
      </div>

      {/* --- Slider Navigation (Bottom Right) --- */}
      <div style={{ 
        position: 'absolute', 
        bottom: 40, 
        right: 60, 
        zIndex: 10, 
        display: 'flex', 
        alignItems: 'center', 
        gap: 24 
      }}>
        <div style={{ display: 'flex', gap: 10 }}>
          {slides.map((_, i) => (
            <div 
              key={i} 
              onClick={() => setCurrent(i)}
              style={{ 
                width: i === current ? 40 : 10, 
                height: 4, 
                borderRadius: 2, 
                background: i === current ? C.gold : 'rgba(255,255,255,0.3)', 
                cursor: 'pointer',
                transition: 'all 0.4s' 
              }} 
            />
          ))}
        </div>
        <div style={{ display: 'flex', gap: 12 }}>
          <button onClick={prev} style={navButtonStyle}>←</button>
          <button onClick={next} style={navButtonStyle}>→</button>
        </div>
      </div>
    </section>
  );
}

const navButtonStyle = {
  width: 50,
  height: 50,
  borderRadius: '50%',
  border: '1px solid rgba(255,255,255,0.2)',
  background: 'rgba(255,255,255,0.1)',
  color: '#fff',
  fontSize: '20px',
  cursor: 'pointer',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  backdropFilter: 'blur(5px)',
  transition: '0.3s'
};
